// Test-only TLS termination forwards decrypted bytes to the isolated DAV fixture.
// Its private CA is trusted only by this test process, never installed in Windows.
class DavTlsBridge final:public QTcpServer {
public:
    quint16 target=0;
protected:
    void incomingConnection(qintptr descriptor) override {
        auto* tls=new QSslSocket(this); auto* plain=new QTcpSocket(tls);
        QFile cert(QString(MLASH_SOURCE_DIR)+"/tests/fixtures/webdav/test-cert.pem"),key(QString(MLASH_SOURCE_DIR)+"/tests/fixtures/webdav/test-key.pem");
        if (!cert.open(QIODevice::ReadOnly)||!key.open(QIODevice::ReadOnly)) { tls->deleteLater(); return; }
        tls->setLocalCertificate(QSslCertificate(cert.readAll())); tls->setPrivateKey(QSslKey(key.readAll(),QSsl::Rsa)); tls->setPeerVerifyMode(QSslSocket::VerifyNone);
        tls->setSocketDescriptor(descriptor);
        connect(tls,&QSslSocket::encrypted,plain,[this,plain] { plain->connectToHost(QHostAddress::LocalHost,target); });
        const auto forward=[tls,plain] { if (plain->state()==QAbstractSocket::ConnectedState) plain->write(tls->readAll()); };
        connect(tls,&QIODevice::readyRead,tls,forward); connect(plain,&QTcpSocket::connected,tls,forward);
        connect(plain,&QIODevice::readyRead,tls,[tls,plain] { tls->write(plain->readAll()); });
        connect(plain,&QTcpSocket::disconnected,tls,[tls] { tls->disconnectFromHost(); });
        connect(tls,&QSslSocket::disconnected,tls,&QObject::deleteLater);
        tls->startServerEncryption();
    }
};
static QJsonObject config() { return {{"url","https://remote.example.test/dav/"},{"username","test-user"},{"password","webdav-private-secret"},{"backup_password","portable-private-password"},{"route","direct"},{"allow_private",false},{"enabled",false},{"interval_hours",24}}; }
class DavFixture final {
public:
    MockHttp http; DavTlsBridge tls; QMap<QString,QByteArray> files; bool corruptTemporary=false,rejectMove=false; int status=0,delay=0;
    DavFixture() { http.handler=[this](const QByteArray& request) { const auto first=request.left(request.indexOf("\r\n")).split(' '); const auto method=first.value(0); const auto path=QUrl::fromEncoded(first.value(1)).path(); const auto name=path.section('/',-1); const auto body=request.mid(request.indexOf("\r\n\r\n")+4); if (status) return HttpResponse{status,"sensitive error body webdav-private-secret",delay,status==302?QByteArray("Location: https://other.invalid/\r\n"):QByteArray()};
        if (method=="PUT") { if (files.contains(name)) return HttpResponse{412,{}}; files[name]=body; return HttpResponse{201,{},delay}; }
        if (method=="GET") return files.contains(name)?HttpResponse{200,files[name]+(corruptTemporary&&name.endsWith(".tmp")?"modified":""),delay}:HttpResponse{404,{}};
        if (method=="MOVE") { const auto marker=QByteArray("Destination: "); const auto start=request.indexOf(marker); const auto destination=QUrl(QString::fromUtf8(request.mid(start+marker.size()).split('\r').first())).path().section('/',-1); if (rejectMove||files.contains(destination)) return HttpResponse{412,{}}; files[destination]=files.take(name); return HttpResponse{201,{}}; }
        if (method=="PROPFIND") { QByteArray xml="<d:multistatus xmlns:d=\"DAV:\">"; for (auto item=files.begin();item!=files.end();++item) xml+="<d:response><d:href>/dav/"+item.key().toUtf8()+"</d:href><d:propstat><d:prop><d:getcontentlength>"+QByteArray::number(item.value().size())+"</d:getcontentlength><d:getlastmodified>Thu, 15 Oct 2026 00:00:00 GMT</d:getlastmodified></d:prop><d:status>HTTP/1.1 200 OK</d:status></d:propstat></d:response>"; xml+="</d:multistatus>"; return HttpResponse{207,xml}; } return HttpResponse{405,{}}; }; }
    bool listen() { return http.listen(QHostAddress::LocalHost); }
    QUrl endpoint() const { return QUrl(QString("http://127.0.0.1:%1/dav/").arg(http.serverPort())); }
    QUrl tlsEndpoint() { tls.target=http.serverPort(); if (!tls.isListening()&&!tls.listen(QHostAddress::LocalHost)) return {}; return QUrl(QString("https://127.0.0.1:%1/dav/").arg(tls.serverPort())); }
    int finalCount() const { int count=0; for (auto file=files.begin();file!=files.end();++file) if (remoteBackupFileName(file.key())) ++count; return count; }
};
class RemotePlatform final:public PlatformServices {
    std::shared_ptr<PlatformServices> real_=createPlatformServices();
public:
    int writes=0; bool failSeal=false,owned=true;
    Result readProxy() override { return {true,{},{{"flags",1},{"server",""},{"bypass",""},{"pac",""}}}; } Result writeProxy(const QJsonObject&) override { ++writes; return Result::fail("prohibited"); } QJsonObject proxyTarget(int) const override { return {}; } bool proxyEnabled(const QJsonObject&) const override { return false; } Result autoStart(bool,const QString&) override { ++writes; return Result::fail("prohibited"); } Result readAutoStart(const QString&) override { return {true,{},{{"enabled",false}}}; }
    Result seal(const QByteArray& in,QByteArray& out) override { return failSeal?Result::fail("injected DPAPI save failure"):real_->seal(in,out); } Result open(const QByteArray& in,QByteArray& out) override { return real_->open(in,out); } Result secureDirectory(const QString& path) override { return real_->secureDirectory(path); } Result attachChild(qint64) override { return {}; } Result ownsTcpPort(qint64,int) override { return {true,{},{{"owned",owned}}}; }
};
