        dialog->findChild<QPushButton*>("uploadRemoteBackup")->click(); QTRY_COMPARE_WITH_TIMEOUT(finished.size(),2,10000); QVERIFY2(finished.last()[0].toBool(),qUtf8Printable(finished.last()[1].toString())); QCOMPARE(server.finalCount(),1); QCOMPARE(c.state().generation,generation); QString name; for (auto file=server.files.begin();file!=server.files.end();++file) if (remoteBackupFileName(file.key())) name=file.key(); const auto encrypted=server.files.value(name); QVERIFY(!encrypted.contains("webdav-private-secret")); QByteArray plain; QVERIFY(openPortable(encrypted,"portable-private-password",plain).ok); const auto archive=QJsonDocument::fromJson(plain).object(); QVERIFY(archive.value("settings").toObject().value("remote_backup").toObject().isEmpty()); QVERIFY(!plain.contains("webdav-private-secret")); QVERIFY(!plain.contains("portable-private-password")); QVERIFY(!c.settings().remoteBackup.value("last_success_utc").toString().isEmpty());
        dialog->findChild<QPushButton*>("listRemoteBackups")->click(); auto* table=dialog->findChild<QTableWidget*>("remoteBackupFiles"); QTRY_COMPARE(table->rowCount(),1); QCOMPARE(table->item(0,0)->text(),name); const auto destination=data.path()+"/downloaded.mlashbackup"; c.downloadRemoteBackup(name,destination); QTRY_COMPARE_WITH_TIMEOUT(downloaded.size(),1,6000); QCOMPARE(c.profiles().size(),0); QVERIFY(!c.state().ready); QVERIFY(BackupArchive::inspect(destination,"portable-private-password").ok); auto* restore=dialog->findChild<BackupDialog*>(); QVERIFY(restore); QCOMPARE(restore->findChild<QLineEdit*>("backupPath")->text(),destination); QVERIFY(!restore->findChild<QPushButton*>("submitBackup")->isEnabled()); restore->reject();
