        const auto beforeRequests=server.http.requests.size(); const auto beforeCancel=finished.size(); c.startRemoteBackup(); c.cancelRemoteBackup(); QTRY_COMPARE_WITH_TIMEOUT(finished.size(),beforeCancel+1,6000); QVERIFY2(finished.last()[0].toBool(),qUtf8Printable(finished.last()[1].toString())); QCOMPARE(finished.last()[1].toString(),QString("远端操作已取消")); QCOMPARE(server.http.requests.size(),beforeRequests); dialog->reject(); QTRY_VERIFY(dialog.isNull()); QCOMPARE(platform->writes,0);
